option.value:
[versions]
jvmTarget = "21"
kotlin = "2.2.20"
# should match kotlin https://github.com/google/ksp/releases
gradlePlugin = "8.11.2"
googleServices = "4.4.4"
crashlyticsPlugin = "3.0.6"
firebaseBOM = "34.4.0"
retrofit = "3.0.0"
kotlinx-serialization = "1.9.0"
retrofit2KotlinxSerializationConverter = "1.0.0"
networkResponseAdapter = "5.0.0"
napier = "2.7.1"
composeNavigation = "2.9.5"
okhttp = "5.2.1"
composePlatform = "2025.10.00"
activityCompose = "1.11.0"
composeLifecycle = "2.9.4"
# Test dependencies
kotlinxCoroutinesTest = "1.10.2"
junit = "4.13.2"
mockkAndroid = "1.14.6"
turbine = "1.2.1"
composeStateEvents = "2.2.0"
koin = "4.1.1"

[libraries]
junit = { module = "junit:junit", version.ref = "junit" }
kotlin-test = { module = "org.jetbrains.kotlin:kotlin-test" }
kotlinx-coroutines-test = { module = "org.jetbrains.kotlinx:kotlinx-coroutines-test", version.ref = "kotlinxCoroutinesTest" }
mockk-agent = { module = "io.mockk:mockk-agent", version.ref = "mockkAndroid" }
mockk-android = { module = "io.mockk:mockk-android", version.ref = "mockkAndroid" }
retrofit = { module = "com.squareup.retrofit2:retrofit", version.ref = "retrofit" }
retrofit2-kotlinx-serialization-converter = { module = "com.jakewharton.retrofit:retrofit2-kotlinx-serialization-converter", version.ref = "retrofit2KotlinxSerializationConverter" }
kotlinx-serialization-json = { module = "org.jetbrains.kotlinx:kotlinx-serialization-json", version.ref = "kotlinx-serialization" }
networkResponseAdapter = { module = "com.github.haroldadmin:NetworkResponseAdapter", version.ref = "networkResponseAdapter" }
okhttp = { module = "com.squareup.okhttp3:okhttp", version.ref = "okhttp" }
okhttpLogging = { module = "com.squareup.okhttp3:logging-interceptor", version.ref = "okhttp" }
napier = { module = "io.github.aakira:napier", version.ref = "napier" }
composeUIGraphics = { module = "androidx.compose.ui:ui-graphics" }
composeUITooling = { module = "androidx.compose.ui:ui-tooling" }
composeUIToolingPreview = { module = "androidx.compose.ui:ui-tooling-preview" }
composeMaterial3 = { module = "androidx.compose.material3:material3" }
composePlatform = { module = "androidx.compose:compose-bom", version.ref = "composePlatform" }
firebaseBoM = { module = "com.google.firebase:firebase-bom", version.ref = "firebaseBOM" }
firebaseCrashlytics = { module = "com.google.firebase:firebase-crashlytics" }
activityCompose = { module = "androidx.activity:activity-compose", version.ref = "activityCompose" }
composeLifecycle = { module = "androidx.lifecycle:lifecycle-runtime-compose", version.ref = "composeLifecycle" }
turbine = { module = "app.cash.turbine:turbine", version.ref = "turbine" }
composeStateEvents = { module = "com.github.leonard-palm:compose-state-events", version.ref = "composeStateEvents" }
composeNavigation = { module = "androidx.navigation:navigation-compose", version.ref = "composeNavigation" }
koin = { module = "io.insert-koin:koin-android", version.ref = "koin" }
koin-compose = { module = "io.insert-koin:koin-androidx-compose", version.ref = "koin" }
koin-test = { module = "io.insert-koin:koin-test-junit4", version.ref = "koin" }

[plugins]
androidApplication = { id = "com.android.application", version.ref = "gradlePlugin" }
androidLibrary = { id = "com.android.library", version.ref = "gradlePlugin" }
kotlinSerialization = { id = "org.jetbrains.kotlin.plugin.serialization", version.ref = "kotlin" }
jetbrainsKotlinAndroid = { id = "org.jetbrains.kotlin.android", version.ref = "kotlin" }
googleServices = { id = "com.google.gms.google-services", version.ref = "googleServices" }
firebaseCrashlyticsPlugin = { id = "com.google.firebase.crashlytics", version.ref = "crashlyticsPlugin" }
compose-compiler = { id = "org.jetbrains.kotlin.plugin.compose", version.ref = "kotlin" }

